// ==================== Cross-version and Format Tests ====================

TEST_F(CompressedTableFixtureTest, CompressedPageFormat_Valid) {
    // Verify that INDEX pages in compressed tablespace have valid FIL headers
    auto ibd = load_ibd("mysql57_t_comp_8k.ibd");
    ASSERT_FALSE(ibd.empty());

    auto pages = find_index_pages(ibd);
    ASSERT_FALSE(pages.empty()) << "Must have INDEX pages";

    // Check the first INDEX page's FIL header fields
    auto [offset, page_no] = pages[0];
    const uint8_t* page = ibd.data() + offset;

    uint32_t pno = read_be<uint32_t>(page + 4, 0);
    uint32_t space_id = read_be<uint32_t>(page + 34, 0);
    uint64_t lsn = read_be<uint64_t>(page + 16, 0);

    EXPECT_GT(space_id, 0u) << "Space ID must be > 0";
    EXPECT_GT(lsn, 0u) << "LSN must be > 0";
    EXPECT_EQ(pno, page_no) << "Page number must match";
}

TEST_F(CompressedTableFixtureTest, CrossVersionSameCompression) {
    // MySQL 5.7 and 8.0 with same KEY_BLOCK_SIZE should have similar layout
    auto ibd57 = load_ibd("mysql57_t_comp_8k.ibd");
    auto ibd80 = load_ibd("mysql80_t_comp_4k.ibd");  // Use comp_4k which has data
    ASSERT_FALSE(ibd57.empty());
    ASSERT_FALSE(ibd80.empty());

    EXPECT_TRUE(has_compressed_layout(ibd57));

    uint16_t page_type80 = read_be<uint16_t>(ibd80.data() + 24, 0);
    if (page_type80 == 0) {
        SUCCEED() << "mysql80_t_comp_4k.ibd has no data, skipping cross-version check";
        return;
    }
    EXPECT_TRUE(has_compressed_layout(ibd80));
}

TEST_F(CompressedTableFixtureTest, AllFilesHaveValidPage0) {
    // Verify that all fixture files have a valid page 0
    struct { const char* name; bool expect_data; } files[] = {
        {"mysql57_t_uncompressed.ibd", true},
        {"mysql57_t_comp_8k.ibd", true},
        {"mysql57_t_comp_4k.ibd", true},
        {"mysql57_t_comp_8k_large.ibd", true},
        {"mysql80_t_uncompressed.ibd", false},   // MySQL 8.0 lazy flush
        {"mysql80_t_comp_8k.ibd", false},        // MySQL 8.0 lazy flush
        {"mysql80_t_comp_4k.ibd", true},
        {"mysql80_t_comp_16k.ibd", true},
        {"mysql80_t_comp_8k_large.ibd", true},
    };

    for (const auto& entry : files) {
        const char* fname = entry.name;
        auto ibd = load_ibd(fname);
        ASSERT_FALSE(ibd.empty()) << fname << " must load";
        ASSERT_GE(ibd.size(), 16384u) << fname << " must be at least 16K";

        // Page 0 should have valid FIL header
        uint32_t space_id = read_be<uint32_t>(ibd.data() + 34, 0);
        uint64_t lsn = read_be<uint64_t>(ibd.data() + 16, 0);
        uint16_t page_type = read_be<uint16_t>(ibd.data() + 24, 0);

        if (!entry.expect_data && page_type == 0) {
            SUCCEED() << fname << " empty (expected for MySQL 8.0 lazy flush)";
            continue;
        }

        EXPECT_GT(space_id, 0u) << fname << " page 0 must have valid space_id";
        EXPECT_GT(lsn, 0u) << fname << " page 0 must have valid LSN";

        // Page 0 is typically FSP_HDR (0x0008), XDES (0x0009), or SYSTEM (0x0006)
        EXPECT_TRUE(page_type == 0x0008 || page_type == 0x0009 || page_type == 0x0006)
            << fname << " page 0 should be FSP_HDR/XDES/SYSTEM, got 0x"
            << std::hex << page_type << std::dec;
    }
}

